import"./hoisted.B-emFZvJ.js";document.querySelectorAll(".btn-add-carrinho").forEach(a=>{a.addEventListener("click",n=>{const t=n.currentTarget,o=t.getAttribute("data-slug")||"",r=t.getAttribute("data-nome")||"",i=parseFloat(t.getAttribute("data-preco")||"0"),c=t.getAttribute("data-unidade")||"un",d=t.getAttribute("data-imagem")||"";if(window.carrinhoMercado){window.carrinhoMercado.adicionar({slug:o,nome:r,preco:i,unidade:c,imagem:d});const e=t.querySelector(".btn-text");if(e){const s=e.textContent;e.textContent="Adicionado! ✓",t.classList.add("bg-emerald-600"),setTimeout(()=>{e.textContent=s,t.classList.remove("bg-emerald-600")},1500)}}})});
